// The EFX-2 lexer and parser, generated by antlr-ng from the pinned grammar files and loaded.
//
// antlr-ng's JavaScript target writes code for the antlr4 runtime; its TypeScript target writes
// code for antlr4ng, the runtime this package uses. The grammar is therefore generated as
// TypeScript and the type annotations are removed with Node's own stripTypeScriptTypes.

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { CharStream, CommonTokenStream, RuleStopState, RuleTransition, Token } from 'antlr4ng';

const ANTLR_NG = fileURLToPath(new URL('../../node_modules/antlr-ng/dist/cli/runner.js', import.meta.url));

// Under the repository, so that the generated modules resolve antlr4ng when they are imported
// (they would not from the system's temporary folder), and in node_modules/.cache, which git
// ignores.
const WORK_FOLDER = fileURLToPath(new URL('../../node_modules/.cache/', import.meta.url));

const QUOTED_WORD = /'([A-Za-z_][\w-]*)'/g;

export class AntlrGrammar {
  #lexerGrammar;
  #parserGrammar;
  #lexerModule;
  #parserModule;
  #Lexer;
  #Parser;

  constructor(grammars, modules, Lexer, Parser) {
    this.#lexerGrammar = grammars.lexer;
    this.#parserGrammar = grammars.parser;
    this.#lexerModule = modules.lexer;
    this.#parserModule = modules.parser;
    this.#Lexer = Lexer;
    this.#Parser = Parser;
  }

  /** Generates the lexer and the parser from the bytes of EfxLexer.g4 and Efx.g4. */
  static async generate(lexerGrammar, parserGrammar) {
    fs.mkdirSync(WORK_FOLDER, { recursive: true });
    const folder = fs.mkdtempSync(path.join(WORK_FOLDER, 'efx-sync-'));
    try {
      fs.writeFileSync(path.join(folder, 'EfxLexer.g4'), lexerGrammar);
      fs.writeFileSync(path.join(folder, 'Efx.g4'), parserGrammar);
      execFileSync(process.execPath, [ANTLR_NG, '-Dlanguage=TypeScript', '--generate-listener', 'false',
        '-o', folder, 'EfxLexer.g4', 'Efx.g4'], { cwd: folder, stdio: 'inherit' });
      const lexerModule = AntlrGrammar.#javaScriptOf(folder, 'EfxLexer');
      const parserModule = AntlrGrammar.#javaScriptOf(folder, 'EfxParser');
      const { EfxLexer } = await import(pathToFileURL(lexerModule.file));
      const { EfxParser } = await import(pathToFileURL(parserModule.file));
      return new AntlrGrammar({ lexer: lexerGrammar, parser: parserGrammar },
        { lexer: lexerModule.text, parser: parserModule.text }, EfxLexer, EfxParser);
    } finally {
      fs.rmSync(folder, { recursive: true, force: true });
    }
  }

  /** The words quoted in EfxLexer.g4, once each and sorted. */
  quotedWords() {
    const words = Array.from(this.#lexerGrammar.toString('utf8').matchAll(QUOTED_WORD), (match) => match[1]);
    return [...new Set(words)].sort();
  }

  /**
   * The name of the token the lexer makes of a text when it reads it in the given mode, or
   * undefined when the text is not exactly one token there.
   */
  tokenOf(text, modeName) {
    const lexer = new this.#Lexer(CharStream.fromString(text));
    lexer.removeErrorListeners();
    lexer.pushMode(AntlrGrammar.#indexOf(this.#Lexer.modeNames, modeName, 'lexer mode'));
    const tokens = lexer.getAllTokens();
    return tokens.length === 1 && tokens[0].text === text
      ? lexer.vocabulary.getSymbolicName(tokens[0].type)
      : undefined;
  }

  /**
   * The names of the tokens the parser reads only as the first token of the given rule: the tokens
   * that can start it and that no other transition of the parser reads. Each transition says which
   * tokens it reads, so a wildcard or a negated set is read as what it matches.
   */
  tokensReadOnlyAtStartOf(ruleName) {
    const parser = this.#parser();
    const { atn } = parser;
    const opening = AntlrGrammar.#openingTransitions(parser, ruleName);
    const others = atn.states.flatMap((state) => state.transitions)
      .filter((transition) => !transition.isEpsilon && !opening.has(transition));
    const types = AntlrGrammar.#firstTypes(parser, ruleName).filter((type) =>
      !others.some((transition) => transition.matches(type, Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType)));
    return AntlrGrammar.#namesOf(parser, types);
  }

  /**
   * The files of test/oracle/: the grammars as pinned, and the lexer and parser generated from
   * them.
   */
  oracleFiles(source) {
    const generated = (grammarFile, module) =>
      `// Generated by \`npm run sync\` with antlr-ng from ${grammarFile} at ${source}. Do not edit.\n${module}`;
    return new Map([
      ['EfxLexer.g4', this.#lexerGrammar],
      ['EfxLexer.js', generated('EfxLexer.g4', this.#lexerModule)],
      ['Efx.g4', this.#parserGrammar],
      ['EfxParser.js', generated('Efx.g4', this.#parserModule)],
    ]);
  }

  #parser() {
    return new this.#Parser(new CommonTokenStream(new this.#Lexer(CharStream.fromString(''))));
  }

  static #startOf(parser, ruleName) {
    return parser.atn.ruleToStartState[AntlrGrammar.#indexOf(parser.ruleNames, ruleName, 'parser rule')];
  }

  static #firstTypes(parser, ruleName) {
    return parser.atn.nextTokens(AntlrGrammar.#startOf(parser, ruleName)).toArray();
  }

  static #namesOf(parser, types) {
    return new Set(types.map((type) => parser.vocabulary.getSymbolicName(type)));
  }

  /**
   * The transitions that read the first token of a rule: those that read a token and that the
   * parser reaches from the rule's start without reading one, entering the rules it starts with.
   * They read the first token of this rule only, so the rules it enters on the way must be used
   * nowhere else, and none of them may end before a token is read; the sync stops otherwise.
   */
  static #openingTransitions(parser, ruleName) {
    const calls = parser.atn.states.flatMap((state) => state.transitions)
      .filter((transition) => transition instanceof RuleTransition);
    const isCalledElsewhere = (call) => calls.some((other) => other !== call && other.target === call.target);
    const opening = new Set();
    const visited = new Set();
    const pending = [AntlrGrammar.#startOf(parser, ruleName)];
    while (pending.length > 0) {
      const state = pending.pop();
      if (state instanceof RuleStopState) {
        AntlrGrammar.#cannotTell(parser, ruleName, state.ruleIndex, 'can end before a token is read');
      }
      if (!visited.has(state)) {
        visited.add(state);
        for (const transition of state.transitions) {
          if (transition instanceof RuleTransition && isCalledElsewhere(transition)) {
            AntlrGrammar.#cannotTell(parser, ruleName, transition.ruleIndex, 'is also used elsewhere');
          }
          if (transition.isEpsilon) {
            pending.push(transition.target);
          } else {
            opening.add(transition);
          }
        }
      }
    }
    return opening;
  }

  /** Stops the sync when a rule met at the start of the given rule breaks #openingTransitions' assumption. */
  static #cannotTell(parser, ruleName, ruleIndex, reason) {
    throw new Error(`At the start of ${ruleName}, rule ${parser.ruleNames[ruleIndex]} ${reason}: `
      + `the sync cannot tell which tokens the parser reads only as the first token of ${ruleName}`);
  }

  /** The index of a mode or rule, so that a name the grammar no longer has stops the sync. */
  static #indexOf(names, name, kind) {
    const index = names.indexOf(name);
    if (index < 0) {
      throw new Error(`The grammar has no ${kind} named ${name}`);
    }
    return index;
  }

  static #javaScriptOf(folder, name) {
    const file = path.join(folder, `${name}.js`);
    const text = stripTypeScriptTypes(fs.readFileSync(path.join(folder, `${name}.ts`), 'utf8'));
    fs.writeFileSync(file, text);
    return { file, text };
  }
}
